#!/usr/bin/env python3
# In a notebook, do not edit this file. It is generic - the template's, listed
# in .claude/notebook/manifest.txt - and the update skill replaces it; the
# notebook's pre-commit hook refuses a commit that changes it. To extend:
#   - a setting or an audit rule: .scripts/notebook_config.py
#   - an operation or a check of the notebook's own: a script of its own in
#     .scripts/ that imports this one, never a copy of it
#   - a rule for one type: that type's declaration in Types/
#   - a fix every notebook needs: ask the template for it, with an issue -
#     .claude/notebook/requests.md
# The whole table: .claude/notebook/upstream.md, "The outlets".
"""The notebook's operations: what the skills call to change it.

  new <type> [<name>] [--owner O] [--source S ...] [--alias A ...] [--set field=value ...]
                                                       create a page from its declaration
  graph [--print]                                      derive the graph view's colour groups and filter from Types/
  open <name> [--type T] [--owner O] [--set field=value ...]
                                                       open a ledger entry, or a prepared one
  prepare <name> [--type T] [--owner O] [--set field=value ...]
                                                       a ledger entry a projection writes, before it opens
  fill <entry> <section> [--file F]                    a prepared entry's section, from F or stdin
  close [<name>]                                       close one; with no name, the only open one
  resume <name>                                        make a closed entry active again
  current                                              the open and prepared entries, and any ledger that needs one
  log <line> [--local] [--section S] [--to <name>]     append to an open entry
  tree                                                 move each page to its bucket, and write each owned page's `parent:`
  clues <page>                                         what in a page's sections already acts like pages of their own
  rename <page> <new name> [--dry-run]                 rename an entity, its folder, and the pages named from it

Nothing here knows any type's particulars. Folders, required fields and their
starting values all come from the declarations in Types/ - see
.claude/notebook/registry.md - so declaring a type is enough for this to make
pages of it. Which types are ledgers is declared the same way, with `ledger:`,
and which own which with `parents:` (.claude/notebook/graph.md, "Ownership").
"""
import hashlib, json, os, pathlib, re, subprocess, sys
# `python3 -I` isolates sys.path, which drops this script's own directory -
# so the config beside it is not importable without putting it back.
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import notebook_config as cfg

VAULT = pathlib.Path(__file__).resolve().parents[1]


# ---------------------------------------------------------------- the registry
def _list(fm, key):
    m = re.search(rf"^{key}:[ \t]*\n((?:[ \t]*-[ \t]*\S.*\n?)+)", fm, re.M)
    return [l.strip().lstrip("-").strip() for l in m.group(1).splitlines()] if m else []

def _item(x):
    """One YAML list item: a quoted one's content, or a bare one without a
    trailing comment - `- '^(\\d{4})'   # the year` is the regex alone."""
    x = x.strip()
    m = re.match(r"""^(['"])(.*)\1(?:\s+#.*)?$""", x)
    return m.group(2) if m else re.sub(r"\s+#.*$", "", x)

def _items(fm, key):
    """A list written either way YAML allows: inline, `key: [a, b]`, or as a block."""
    m = re.search(rf"^{key}:[ \t]*\[(.*)\][ \t]*$", fm, re.M)
    if m:
        return [_item(x) for x in m.group(1).split(",") if x.strip()]
    return [_item(x) for x in _list(fm, key)]

def _map(fm, key):
    m = re.search(rf"^{key}:[ \t]*\n((?:[ \t]+[a-z_]+:.*\n?)+)", fm, re.M)
    if not m:
        return {}
    return {k.strip(): v.strip() for k, v in
            (l.split(":", 1) for l in m.group(1).splitlines() if ":" in l)}

def _sections(fm):
    """The headings every page of the type has, in order (registry.md).

    Absent means the default layout: Known then My reading, or Known alone
    for a relation. `sections: []` means a page with no headings at all, for
    a verbatim text.
    """
    if re.search(r"^sections:[ \t]*\[\][ \t]*$", fm, re.M):
        return []
    relation = _scalar(fm, "relation") == "true"
    return _items(fm, "sections") or (["Known"] if relation else ["Known", "My reading"])

def _scalar(fm, key):
    m = re.search(rf"^{key}:[ \t]*(\S.*?)[ \t]*$", fm, re.M)
    return m.group(1) if m else None

def registry():
    """type -> {folder, required, defaults, sections, links, ledger...}, from each declaration."""
    out = {}
    for t in sorted((VAULT / cfg.TYPES_DIR).glob("*.md")):
        fm = t.read_text(encoding="utf-8").split("\n---\n", 1)[0] + "\n"
        d = re.search(r"^declares:[ \t]*(\S+)", fm, re.M)
        f = re.search(r"^folder:[ \t]*(.+)$", fm, re.M)
        if not d or not f or f.group(1).strip().startswith("("):
            continue
        identity = _scalar(fm, "identity") or "name"
        out[d.group(1)] = {"folder": f.group(1).strip(),
                           "required": [r for r in _list(fm, "required") if r != "type"],
                           "defaults": _map(fm, "defaults"),
                           "sections": _sections(fm),
                           "links": _map(fm, "links"),
                           "parents": _items(fm, "parents"),
                           "identity": identity,
                           "pattern": (_scalar(fm, "name") or "{%s}" % identity).strip("\"'"),
                           "prepared": _items(fm, "prepared"),
                           "buckets": _items(fm, "buckets"),
                           **{k: _scalar(fm, k) for k in ("ledger", "log_to", "occasion_only",
                                                          "relation", "generated", "aspect",
                                                          "graph_color")}}
    # A section written `- <heading>: <type>` is filled by the pages of that
    # type its page owns (graph.md, "Ownership"). Only a declared type makes
    # it one, so a heading that merely contains a colon stays a heading.
    for d in out.values():
        d["slots"], heads = {}, []
        for s in d["sections"]:
            head, _, child = s.rpartition(": ")
            if head and child in out:
                d["slots"][head] = child
                heads.append(head)
            else:
                heads.append(s)
        d["sections"] = heads
    return out


# ---------------------------------------------------------------- pages
def yaml_scalar(v):
    """One YAML scalar, quoted the way Obsidian's parser needs.

    A double-quoted scalar may not hold an unescaped double quote, and when the
    YAML fails Obsidian drops the WHOLE frontmatter block - type, aliases and
    source vanish together while the page looks fine and nothing reports it.
    Single-quoting is the fix: single-quoted YAML permits inner doubles.
    """
    if '"' in v:
        return "'" + v.replace("'", "''") + "'"
    if any(c in v for c in ':#[]|&*{}>!%@`') or v != v.strip():
        return '"' + v + '"'
    return v

def as_source(v):
    """A source: entry - a link when the thing already has a page, else a plain
    string. Naming a concept is the user's call, not this script's."""
    hit = next((q for q in VAULT.rglob(v + ".md")
                if not any(x.startswith(".") for x in q.parts)), None)
    return '"[[' + v + ']]"' if hit else yaml_scalar(v)

def as_link(v):
    """A value for a field declared in `links:` (registry.md): always a quoted
    wikilink, whether or not the target has a page yet - a dangling link means
    named, not yet filed. Never a stub to make it resolve. A value given
    already quoted, as frontmatter writes it, loses its quotes first."""
    v = v.strip()
    if len(v) > 1 and v[0] == v[-1] and v[0] in "\"'":
        v = v[1:-1].strip()
    return '"' + (v if v.startswith("[[") else "[[" + v + "]]") + '"'

def list_fields(typ):
    """Fields some page of this type already writes as a block list. A value
    set with --set follows that convention even when there is only one, so a
    field is not a list on some pages and a scalar on others. Per type: two
    types may share a field name and mean different things by it."""
    keys = set()
    for q in VAULT.rglob("*.md"):
        if any(x.startswith(".") for x in q.relative_to(VAULT).parts):
            continue
        head = q.read_text(encoding="utf-8", errors="replace").split("\n---\n", 1)[0]
        if re.search(rf"^type:[ \t]*{re.escape(typ)}[ \t]*$", head, re.M):
            keys |= set(re.findall(r"^([a-z_]+):[ \t]*\n[ \t]*-[ \t]", head + "\n", re.M))
    return keys

def new(typ, name, sources=(), aliases=(), sets=(), owner=None):
    reg = registry()
    if typ in ledgers():
        sys.exit(f"{typ} is a ledger: an entry is opened, not created - use `open`")
    if typ not in reg:
        sys.exit(f"undeclared type: {typ} (declared: {', '.join(sorted(t for t in reg if not reg[t]['ledger'])) or 'none yet'}). "
                 f"Declare it first - a page in {cfg.TYPES_DIR}/.")
    p, title, o = _place(typ, name, owner, reg)
    if p.exists():
        sys.exit(f"already exists: {p.relative_to(VAULT)}")
    p.parent.mkdir(parents=True, exist_ok=True)
    fm = ["---", f"type: {typ}"] + ([f'parent: "[[{o.stem}]]"'] if o else [])
    for key, vals in (("aliases", aliases), ("source", sources)):
        if vals:
            fm.append(f"{key}:")
            fm += [f"  - {as_source(v) if key == 'source' else yaml_scalar(v)}" for v in vals]
    _write_page(p, title, typ, reg[typ], fm, _given(sets), reg)
    return p

def _given(sets):
    given = {}
    for s in sets:
        if "=" not in s:
            sys.exit(f"--set takes field=value, not {s!r}")
        k, v = s.split("=", 1)
        given.setdefault(k.strip(), []).append(v.strip())
    return given

def _write_page(p, name, typ, d, fm, given, reg=None):
    """The rest of a page from its declaration: each required field - given,
    defaulted or left to fill - then any other field given, then the headings."""
    write = lambda k, v: as_link(v) if k in d["links"] else yaml_scalar(v)
    as_list = list_fields(typ) if given else set()
    unfilled = []
    for key in d["required"] + [k for k in given if k not in d["required"]]:
        if key in given:
            vals = given[key]
            fm += [f"{key}: {write(key, vals[0])}"] if len(vals) == 1 and key not in as_list else \
                  [f"{key}:"] + [f"  - {write(key, v)}" for v in vals]
        elif key in d["defaults"]:
            fm.append(f"{key}: {d['defaults'][key]}")
        else:
            fm.append(f"{key}:")
            unfilled.append(key)
    fm += ["---", "", f"# {name}", ""]
    for section in d["sections"]:
        fm += [f"## {section}", ""]
        if section in d.get("slots", {}):
            fm += [f"![[{_owned_view(d['slots'][section], reg or registry())}#{OWNED_HERE}]]", ""]
    p.write_text("\n".join(fm), encoding="utf-8")
    if unfilled:
        print(f"required with no default, fill these: {', '.join(unfilled)}", file=sys.stderr)


# ---------------------------------------------------------------- ownership
# A page may be owned by another, to any depth (graph.md, "Ownership"). The
# path is the truth: a type folder holds its pages, and a page that owns
# anything becomes a folder named by its identity, holding its own page and
# the type folders of what it owns. `parent:` is written from the path, so
# the graph, backlinks and views see it; nobody edits it by hand.
OWNED_HERE = "Owned here"

def _page_type(p):
    try:
        head = p.read_text(encoding="utf-8", errors="replace")
    except OSError:
        return None
    if not head.startswith("---\n"):
        return None
    m = re.search(r"^type:[ \t]*(\S+)", head.split("\n---\n", 1)[0], re.M)
    return m.group(1) if m else None

def pages(types=None):
    """(type, path) for every page, or every page of these types."""
    for q in sorted(VAULT.rglob("*.md")):
        if any(x.startswith(".") for x in q.relative_to(VAULT).parts):
            continue
        t = _page_type(q)
        if t and (types is None or t in types):
            yield t, q

def _type_dir(p, folder):
    """The type folder a page sits in: the nearest folder of that name above
    it - past its bucket folders (registry.md, "Buckets") and its own entity
    folder, once it owns things."""
    for a in p.parents:
        if a == VAULT:
            return None
        if a.name == folder:
            return a
    return None

def _buckets(d, stem):
    """The bucket folders a page's name puts it in: one per layer of its type's
    `buckets:`, in order, stopping at the first layer its name does not match.
    A bucket is a browsing convenience; the name is the page's whole identity."""
    out = []
    for rx in d.get("buckets", []):
        m = re.search(rx, stem)
        if not m:
            break
        out.append(_filename(m.group(1) if m.groups() else m.group(0)))
    return out

def _is_own(p, d, td):
    """Whether the folder a page is in is its own entity folder - it owns
    things - rather than its type folder or a bucket. Its own is named by its
    identity, read out of its name, so a bucket is never mistaken for one."""
    if td is None or p.parent == td or d["identity"] == "none":
        return False
    m = _pattern_rx(d["pattern"]).match(p.stem)
    ident = m.group(d["identity"]) if m and d["identity"] in m.groupdict() else p.stem
    return p.parent.name == _filename(ident)

def _home(p, reg):
    """Where a page belongs: its type folder, the buckets its name puts it in,
    and its own folder if it owns things. None for a page outside its type's
    folder, which the type check reports instead."""
    d = reg.get(_page_type(p))
    td = _type_dir(p, d["folder"]) if d else None
    if td is None:
        return None
    base = td.joinpath(*_buckets(d, p.stem))
    return base / p.parent.name / p.name if _is_own(p, d, td) else base / p.name

def _own_page(entity_dir):
    """The page an entity folder is for: the one page directly inside it."""
    pages = sorted(entity_dir.glob("*.md"))
    return pages[0] if len(pages) == 1 else None

def owner_of(p, reg=None):
    reg = reg or registry()
    t = _page_type(p)
    if t not in reg:
        return None
    td = _type_dir(p, reg[t]["folder"])
    if td is None or td.parent == VAULT:
        return None
    return _own_page(td.parent)

def _pattern_rx(pattern):
    """A filename pattern as a regex, each {variable} a named group - repeated
    ones matched back to their first."""
    seen, out = set(), ""
    for lit, var in re.findall(r"([^{]*)(?:\{(\w+)\})?", pattern):
        out += re.escape(lit)
        if var:
            out += f"(?P={var})" if var in seen else f"(?P<{var}>.+?)"
            seen.add(var)
    return re.compile(f"^{out}$")

def identity_of(p, reg=None):
    """A page's own variable: its folder's name once it owns things, else read
    back out of its filename through its type's pattern."""
    reg = reg or registry()
    d = reg.get(_page_type(p))
    if not d or d["identity"] == "none":
        return None
    if _is_own(p, d, _type_dir(p, d["folder"])):
        return p.parent.name
    m = _pattern_rx(d["pattern"]).match(p.stem)
    return m.group(d["identity"]) if m and d["identity"] in m.groupdict() else p.stem

def variables(p, reg=None):
    """Every variable in scope at a page: each page above it sets its type's
    identity, and the nearest one wins (registry.md, "Names")."""
    reg = reg or registry()
    chain = []
    while p is not None and p not in chain:
        chain.append(p)
        p = owner_of(p, reg)
    out = {}
    for q in reversed(chain):
        d = reg.get(_page_type(q))
        if d and d["identity"] != "none":
            out[d["identity"]] = identity_of(q, reg)
    return out

def _filename(title):
    return title.replace("/", "-").replace(":", " -").strip()

def _render(d, values):
    try:
        return d["pattern"].format(**values)
    except KeyError as e:
        sys.exit(f"the name pattern {d['pattern']!r} uses {{{e.args[0]}}}, which nothing above it sets")

def _find_owner(name, kinds, reg):
    hits = [q for t, q in pages(set(kinds)) if q.stem == name or identity_of(q, reg) == name
            or q.relative_to(VAULT).with_suffix("").as_posix() == name]
    if not hits:
        sys.exit(f"no {' or '.join(kinds)} called {name!r} to own it")
    if len(hits) > 1:
        sys.exit(f"{name!r} could be any of: " + ", ".join(str(q.relative_to(VAULT)) for q in hits)
                 + " - give its path")
    return hits[0]

def _foldered(p, reg):
    """The entity folder for a page, making it one if it is still a plain file
    - its first owned page is arriving. The filename is kept, so every link to
    it still lands."""
    d = reg[_page_type(p)]
    td = _type_dir(p, d["folder"])
    if td is None:
        sys.exit(f"{p.relative_to(VAULT)} is not in its type's folder, {d['folder']}/")
    if _is_own(p, d, td):
        return p.parent
    if d["identity"] == "none":
        sys.exit(f"{p.relative_to(VAULT)} is one per owner, with no name of its own, so it owns nothing")
    dest = p.parent / _filename(identity_of(p, reg))
    if dest.exists():
        sys.exit(f"cannot make {p.relative_to(VAULT)} a folder: {dest.relative_to(VAULT)} is taken")
    dest.mkdir()
    p.rename(dest / p.name)
    print(f"moved {p.relative_to(VAULT)} into {dest.relative_to(VAULT)}/, its first owned page arriving",
          file=sys.stderr)
    return dest

def _place(typ, value, owner, reg):
    """(path, title, owner page) for a new page of a type, named by its
    pattern from the variables in scope where it will live."""
    d = reg[typ]
    if d["parents"]:
        if not owner:
            sys.exit(f"a {typ} is owned by a {' or '.join(d['parents'])}: say whose, with --owner")
        o = _own_page(_foldered(_find_owner(owner, d["parents"], reg), reg))
        above = variables(o, reg)
        if d["identity"] != "none" and value:
            # Given its whole name rather than its own part - `Tap - Kitchen -
            # 12 Elm Street` for `Tap` - it is read back out of the name, so
            # the owner's part is not added twice.
            m = _pattern_rx(d["pattern"]).match(value)
            if (m and m.group(d["identity"]) != value
                    and all(m.group(k) == v for k, v in above.items() if k in m.groupdict() and k != d["identity"])):
                value = m.group(d["identity"])
        values = {**above, **({} if d["identity"] == "none" else {d["identity"]: value})}
        title = _render(d, values)
        folder = (o.parent / d["folder"]).joinpath(*_buckets(d, _filename(title)))
        return folder / f"{_filename(title)}.md", title, o
    if owner:
        sys.exit(f"a {typ} is top-level: nothing owns it (its declaration has no parents:)")
    if value is None:
        sys.exit(f"a {typ} needs a name")
    title = _render(d, {d["identity"]: value})
    folder = (VAULT / d["folder"]).joinpath(*_buckets(d, _filename(title)))
    return folder / f"{_filename(title)}.md", title, None

def _set_field(p, key, value):
    t = p.read_text(encoding="utf-8")
    end = t.find("\n---\n", 3)
    head, rest = t[:end], t[end:]
    line = f"{key}: {value}"
    head = re.sub(rf"^{key}:.*$", line, head, count=1, flags=re.M) if re.search(rf"^{key}:", head, re.M) \
        else head.replace("\n", f"\n{line}\n", 1)
    p.write_text(head + rest, encoding="utf-8")

def _prune(folder, stop):
    """Remove the bucket folders a move left empty, up to the type folder."""
    while folder != stop and VAULT in folder.parents and folder.is_dir() and not any(folder.iterdir()):
        folder.rmdir()
        folder = folder.parent

def tree():
    """Put every page where its declaration says - in the buckets its name
    puts it in - then write `parent:` on every owned page from where it is.
    Both are derived, so a declaration changed later is caught up by running
    this again, and a page moved by hand to another owner has its link
    follow. A move changes no name and no word, so every link still lands.
    Returns (moved, linked)."""
    reg, moved = registry(), []
    for _ in range(10):                    # an entity moved whole carries pages that may move next
        step = []
        for t, p in list(pages(set(reg))):
            if not p.exists():
                continue                   # moved already, inside its entity folder
            home = _home(p, reg)
            if home is None or home == p:
                continue
            d = reg[t]
            td = _type_dir(p, d["folder"])
            src, dst = (p.parent, home.parent) if _is_own(p, d, td) else (p, home)
            if dst.exists():
                print(f"left {src.relative_to(VAULT)}: {dst.relative_to(VAULT)} is taken", file=sys.stderr)
                continue
            dst.parent.mkdir(parents=True, exist_ok=True)
            old = src.parent
            src.rename(dst)
            _prune(old, td)
            step.append((src, dst))
        moved += step
        if not step:
            break
    linked = []
    owned = {t for t, d in reg.items() if d["parents"]}
    for t, p in pages(owned):
        o = owner_of(p, reg)
        want = f'"[[{o.stem}]]"' if o else None
        m = re.search(r"^parent:[ \t]*(.*)$", p.read_text(encoding="utf-8").split("\n---\n", 1)[0], re.M)
        if want and (not m or m.group(1).strip() != want):
            _set_field(p, "parent", want)
            linked.append(p)
    return moved, linked

def _owned_view(child, reg):
    """The view a section filled by owned pages embeds: one per owned type,
    with a view of the pages the embedding page owns. Made if it is missing;
    a view is configuration over the data, so it is the host's to change."""
    d = reg[child]
    p = VAULT / cfg.VIEWS_DIR / f"{d['folder']}.base"
    if not p.exists():
        p.parent.mkdir(exist_ok=True)
        p.write_text(f"""filters:
  and:
    - type == "{child}"
views:
  - type: table
    name: All
    order:
      - file.name
      - parent
  - type: table
    name: {OWNED_HERE}
    filters:
      and:
        - parent == this
    order:
      - file.name
""", encoding="utf-8")
    return p.name


# ---------------------------------------------------------------- the graph view
# The graph view's colour groups and filter are DERIVED from the declarations
# (.claude/notebook/graph.md, "Seeing it"), so nobody maintains them by hand:
# one group per type, by its type property, and the machinery filtered out. A type's
# colour is a fixed function of its name, so declaring a new type never
# reshuffles the others; `graph_color: "#rrggbb"` on a declaration pins one.
PALETTE = ["#e6194b", "#3cb44b", "#ffe119", "#4363d8", "#f58231", "#911eb4", "#46f0f0",
           "#f032e6", "#bcf60c", "#fabebe", "#008080", "#e6beff", "#9a6324", "#fffac8",
           "#800000", "#aaffc3", "#808000", "#ffd8b1", "#000075", "#808080"]

def _rgb(hexcolor):
    return {"a": 1, "rgb": int(hexcolor.strip().strip('"\'').lstrip("#"), 16)}

def _type_query(t):
    # The type property, anchored: a group is a type, and two types can share
    # a folder. Unanchored, a property search matches substrings (tested
    # 2026-10-25), so a type would also match any longer name containing it.
    return f"[type:/^{re.escape(t)}$/]"

def _folder_query(folder):
    # Quoted, with the slash: a bare path:X is a substring match, so it would
    # also catch a page elsewhere with X in its name (tested 2026-10-25). The
    # substring match is also what finds an owned type's folder at any depth.
    return f'path:"{folder}/"'

def graph_settings():
    reg = registry()
    groups = [{"query": q, "color": _rgb(c)} for q, c in cfg.GRAPH_EXTRA]
    shown = {t: d for t, d in sorted(reg.items()) if not d["ledger"] and d["generated"] != "true"}
    used = {d["graph_color"].strip('"\'').lower() for d in shown.values() if d["graph_color"]}
    for t, d in shown.items():
        color = d["graph_color"]
        if not color:
            # Unpinned: a colour fixed by the type's name, moved on past any
            # colour already taken. Pin it with graph_color: to keep it.
            start = int(hashlib.md5(t.encode()).hexdigest(), 16) % len(PALETTE)
            color = next((PALETTE[(start + k) % len(PALETTE)] for k in range(len(PALETTE))
                          if PALETTE[(start + k) % len(PALETTE)] not in used), PALETTE[start])
            print(f"{t}: no graph_color, so {color} - pin it on the declaration to keep it", file=sys.stderr)
        used.add(color.strip('"\'').lower())
        groups.append({"query": _type_query(t), "color": _rgb(color)})
    hide = sorted({d["folder"] for d in reg.values() if d["ledger"] or d["generated"] == "true"}
                  | {cfg.TYPES_DIR, cfg.VIEWS_DIR})
    search = " ".join([f'-{_folder_query(f)}' for f in hide]
                      + [f'-file:"{cfg.HUB[:-3]}"'] + list(cfg.GRAPH_EXCLUDE))
    return groups, search

_THIS_VAULT = None

def app_is_this_vault():
    """Whether the running app's vault of this folder's name is this folder.
    The CLI finds a vault by its name alone, so a clone or a second checkout
    with the same folder name would otherwise be answered - or written to -
    by the other one."""
    global _THIS_VAULT
    if _THIS_VAULT is None:
        try:
            r = subprocess.run(["obsidian", f"vault={VAULT.name}", "eval", "code=app.vault.adapter.basePath"],
                               capture_output=True, text=True, timeout=20)
            out = r.stdout.strip()
            _THIS_VAULT = (r.returncode == 0 and out.startswith("=>")
                           and os.path.realpath(out[2:].strip()) == os.path.realpath(VAULT))
        except (OSError, subprocess.SubprocessError):
            _THIS_VAULT = False
    return _THIS_VAULT

def graph(apply=True):
    """Set the graph view's colorGroups and search, and nothing else.

    Through the running app when it answers - the graph plugin's own options,
    saved by it and pushed to any open graph view - and otherwise into
    .obsidian/graph.json, which the app reads on start (obsidian.md)."""
    groups, search = graph_settings()
    if not apply:
        return groups, search, "printed"
    code = ("(async()=>{const i=app.internalPlugins.getPluginById('graph').instance;"
            f"i.options.colorGroups={json.dumps(groups)};i.options.search={json.dumps(search)};"
            "await i.saveOptions();app.workspace.getLeavesOfType('graph')"
            ".forEach(l=>l.view.dataEngine.setOptions(i.options));"
            "const ng=app.plugins.plugins['notebook-graph'];if(ng)ng.syncAll(true);return 'ok'})()")
    try:
        out = app_is_this_vault() and subprocess.run(["obsidian", f"vault={VAULT.name}", "eval", f"code={code}"],
                                                     capture_output=True, text=True, timeout=30).stdout
        if out and "ok" in out:
            return groups, search, "the running app"
    except (OSError, subprocess.SubprocessError):
        pass
    p = VAULT / ".obsidian" / "graph.json"
    data = json.loads(p.read_text()) if p.exists() else {}
    data.update(colorGroups=groups, search=search)
    p.parent.mkdir(exist_ok=True)
    p.write_text(json.dumps(data, indent=2))
    return groups, search, str(p.relative_to(VAULT))


# ---------------------------------------------------------------- the ledger
# Which types are ledgers is declared: `ledger: periodic` or `ledger: span` on
# the type's page (.claude/notebook/registry.md). Nothing here knows what the
# host calls an occasion, or how many kinds of occasion it has. An entry is
# prepared (a projection may still rewrite it), open (append-only) or closed.
STATUS = re.compile(r"^status:[ \t]*(\w+)[ \t]*$", re.M)

def ledgers():
    return {t: d for t, d in registry().items() if d["ledger"]}

def machinery():
    """Folders holding machinery rather than notes: the registry, every ledger,
    and every generated type, wherever an owner puts them. The content audit
    does not ask a log or a projection's output whether it stands on its own,
    and no converter rewrites either (ledger.md law 5, contract.md law 8)."""
    return {cfg.TYPES_DIR} | {d["folder"] for d in registry().values()
                              if d["ledger"] or d["generated"] == "true"}

def _head(p):
    t = p.read_text(encoding="utf-8")
    end = t.find("\n---\n", 3)
    return t, end

def _status(p):
    t, end = _head(p)
    m = STATUS.search(t[:end if end != -1 else len(t)]) if t.startswith("---\n") else None
    return m.group(1) if m else None

def _entries():
    yield from pages(set(ledgers()))

def open_entries():
    """Read, never derived: an entry is active because it says so (ledger.md)."""
    return [(t, p) for t, p in _entries() if _status(p) == "open"]

def prepared_entries():
    return [(t, p) for t, p in _entries() if _status(p) == "prepared"]

def needs_opening():
    """Top-level periodic ledgers with nothing open. Capture must ask which
    occasion it is rather than invent one; a span ledger with nothing open is
    ordinary, and so is an owner with no occasion going on."""
    live = {t for t, _ in open_entries()}
    return [t for t, d in sorted(ledgers().items())
            if d["ledger"] == "periodic" and not d["parents"] and t not in live]

def _ledger(typ):
    ls = ledgers()
    if not ls:
        sys.exit(f"no ledger declared: give a type `ledger: periodic` or `ledger: span` in {cfg.TYPES_DIR}/")
    if typ is None and len(ls) > 1:
        sys.exit("several ledgers, say which with --type: " + ", ".join(sorted(ls)))
    t = typ or next(iter(ls))
    if t not in ls:
        sys.exit(f"not a ledger: {t} (ledgers: {', '.join(sorted(ls))})")
    return t, ls[t]

def _entry(name, typ, sets, owner, status):
    """Make an entry, or find the one these variables name. Shared by open and
    prepare: the same occasion is the same name, so preparing it again finds
    the entry it prepared before."""
    t, d = _ledger(typ)
    reg = registry()
    p, title, o = _place(t, name, owner, reg)
    if p.exists():
        return t, p, False
    if status == "open" and d["ledger"] == "periodic" and o is not None:
        busy = [q for tt, q in open_entries() if tt == t and owner_of(q, reg) == o]
        if busy:
            sys.exit(f"{o.stem} already has an open {t}, {busy[0].stem}: close it first")
    p.parent.mkdir(parents=True, exist_ok=True)
    given = _given(sets)
    given["status"] = [status]
    _write_page(p, title, t, d, ["---", f"type: {t}"] + ([f'parent: "[[{o.stem}]]"'] if o else []),
                given, reg)
    return t, p, True

def open_(name, typ=None, sets=(), owner=None):
    """Open an entry: a new one, or one a projection prepared, which from now
    on is append-only like any other. `sets` fills fields the occasion's
    identity brings - a day number, a date - which a host's own operations
    work out (README, "Where the pieces live"); this never learns how."""
    _checkout()
    t, p, made = _entry(name, typ, sets, owner, "open")
    if not made:
        if _status(p) != "prepared":
            sys.exit(f"already exists: {p.relative_to(VAULT)}")
        _set_status(p, "open")
    return p

def prepare(name, typ=None, sets=(), owner=None):
    """An entry a projection writes before it opens (projection.md): made the
    first time, found again after, and refused once it has opened."""
    t, p, made = _entry(name, typ, sets, owner, "prepared")
    if not made and _status(p) != "prepared":
        sys.exit(f"{p.relative_to(VAULT)} is {_status(p)}: a projection writes an entry only "
                 "until it opens - after that it is the ledger's, append-only")
    return p

def fill(name, section, text):
    """Write a prepared entry's section: only one its ledger lists as
    `prepared:`, and only while the entry is still prepared."""
    t, p = _named(name)
    d = ledgers()[t]
    if _status(p) != "prepared":
        sys.exit(f"{p.stem} is {_status(p)}: only a prepared entry is written by a projection")
    if section not in d["prepared"]:
        sys.exit(f"{t} prepares {', '.join(d['prepared']) or 'no sections'}, not {section!r}: "
                 f"declare it in prepared: on its type")
    lines = p.read_text(encoding="utf-8").split("\n")
    head = f"## {section}"
    if head not in lines:
        lines += ["", head, ""]
    s = lines.index(head)
    e = next((i for i in range(s + 1, len(lines)) if lines[i].startswith("## ")), len(lines))
    body = text.strip("\n").split("\n")
    lines[s + 1:e] = [""] + body + [""]
    p.write_text("\n".join(lines), encoding="utf-8")
    return p

def _named(name):
    hits = [(t, p) for t, p in _entries() if p.stem == name]
    if not hits:
        sys.exit(f"no such entry: {name}")
    if len(hits) > 1:
        sys.exit(f"{name} is an entry in several places: " + ", ".join(str(p.relative_to(VAULT)) for _, p in hits))
    return hits[0]

def _one(name):
    """The entry meant: the named one, or the only open one. Never a guess."""
    if name:
        return _named(name)
    es = open_entries()
    if not es:
        sys.exit("no open entry - open one first")
    if len(es) > 1:
        sys.exit("several are open, say which with --to: " + ", ".join(p.stem for _, p in es))
    return es[0]

def _set_status(p, value):
    t, end = _head(p)
    p.write_text(STATUS.sub(f"status: {value}", t[:end], count=1) + t[end:], encoding="utf-8")

def close(name=None):
    _checkout()
    if not name and not open_entries():
        return None                # nothing open is not an error for close
    _, p = _one(name)
    _set_status(p, "closed")
    return p

def _checkout():
    """The guard, if this checkout lacks it (upstream.md, "The guard"). A
    session commits after opening or closing an occasion, so this is where a
    fresh clone gets it without anyone remembering. Silent when there is
    nothing to do; never in the way of the close or the open."""
    script = VAULT / ".scripts/checkout.py"
    if script.exists() and getattr(cfg, "TEMPLATE_COMMIT", None):
        try:
            subprocess.run([sys.executable, "-I", str(script), "--quiet"], timeout=60)
        except subprocess.TimeoutExpired:
            print("this checkout has no guard yet: setting it up gave no answer - run `checkout.py`",
                  file=sys.stderr)

def resume(name):
    """Make an existing entry active again. Only its status changes - a ledger
    entry is never corrected in place (ledger.md), and reopening is not that."""
    _, p = _named(name)
    _set_status(p, "open")
    return p

def log(line, to=None, local=False, section=None):
    """Append to an open entry: its `log_to:` section, or `occasion_only:` when
    the line is true only of this occasion. `section` is for a host's routing."""
    t, p = _one(to)
    if _status(p) != "open":
        sys.exit(f"{p.stem} is {_status(p)}: only an open entry is logged to")
    d = ledgers()[t]
    section = section or (d["occasion_only"] if local else d["log_to"])
    if not section:
        sys.exit(f"{t} declares no {'occasion_only' if local else 'log_to'}: section - add it to {cfg.TYPES_DIR}/")
    lines = p.read_text(encoding="utf-8").split("\n")
    head = f"## {section}"
    if head not in lines:
        lines += ["", head, ""]
    s = lines.index(head)
    e = next((i for i in range(s + 1, len(lines)) if lines[i].startswith("## ")), len(lines))
    tail = max([i for i in range(s, e) if lines[i].strip()], default=s)
    lines.insert(tail + 1, line if line.startswith("- ") else "- " + line)
    p.write_text("\n".join(lines), encoding="utf-8")
    return p


# ---------------------------------------------------------------- promoting a section
# What in a page's sections already behaves like pages of their own - the
# evidence promotion.md's section test reads. Only what the notes already say:
# links someone wrote, and the shape of the headings. Nothing here infers one.
WIKI = re.compile(r"\[\[([^\[\]|#]+?)(#[^\[\]|]*)?(?:\\?\|[^\[\]]*)?\]\]")

def _sections_of(text):
    out, head = {}, None
    for line in text.split("\n"):
        m = re.match(r"^## (.+?)\s*$", line)
        if m:
            head = m.group(1)
            out[head] = []
        elif head:
            out[head].append(line)
    return out

def clues(name):
    hits = [q for _, q in pages() if q.stem == name]
    if len(hits) != 1:
        sys.exit(f"no single page called {name!r}")
    p = hits[0]
    t = _page_type(p)
    secs = _sections_of(p.read_text(encoding="utf-8"))
    into = {}
    for _, q in pages():
        if q == p:
            continue
        for m in WIKI.finditer(q.read_text(encoding="utf-8", errors="replace")):
            if m.group(1).strip() == p.stem and m.group(2):
                into.setdefault(m.group(2)[1:].split("#")[0].strip(), []).append(q.stem)
    others = [q for tt, q in pages({t}) if q != p]
    declared = set(registry().get(t, {}).get("sections", []))
    theirs = [_sections_of(q.read_text(encoding="utf-8", errors="replace")) for q in others]
    links = lambda text: {m.group(1).strip() for m in WIKI.finditer(text)
                          if not text[max(0, m.start() - 1):m.start()] == "!"}
    rows = []
    for h, body in secs.items():
        text = "\n".join(body)
        own = links(text)
        elsewhere = {l for hh, bb in secs.items() if hh != h for l in links("\n".join(bb))}
        subs = [l[4:].strip() for l in body if l.startswith("### ")]
        under = {k: v for k, v in into.items() if k == h or k in subs}
        # A shape repeated across the type: the section itself where the type
        # does not declare it, or headings of their own inside it where it does.
        n = sum(1 for s in theirs if h in s and (h not in declared or
                any(l.startswith("### ") for l in s[h])))
        rows.append((h, under, sorted(own - elsewhere), subs, n if (h not in declared or subs) else 0))
    print(f"{p.relative_to(VAULT)} - {t}, {len(others)} other page(s) of its type\n")
    for h, under, only, subs, n in rows:
        print(f"## {h}")
        for k, who in sorted(under.items()):
            print(f"  linked into, as [[{p.stem}#{k}]]: from {', '.join(sorted(set(who)))}")
        if only:
            print(f"  links only this section makes: {', '.join(only)}")
        if subs:
            print(f"  its own headings: {', '.join(subs)}")
        if n:
            print(f"  the same shape on {n} other {t} page(s)")
        if not (under or only or subs or n):
            print("  nothing")
    return rows


# ---------------------------------------------------------------- renaming
def _app():
    """The running app answering for this vault, or None (obsidian.md)."""
    if not app_is_this_vault():
        return None
    try:
        r = subprocess.run(["obsidian", f"vault={VAULT.name}", "eval", "code=app.vault.getConfig('alwaysUpdateLinks')"],
                           capture_output=True, text=True, timeout=20)
    except (OSError, subprocess.SubprocessError):
        return None
    return r.stdout.strip() if r.returncode == 0 and r.stdout.strip().startswith("=>") else None

def rename_plan(name, value):
    """What renaming an entity's own variable to `value` touches: its page, its
    folder, and every page below it named from that variable - but not a
    ledger entry, whose name was fixed when it was made (ledger.md law 1)."""
    reg = registry()
    hits = [q for _, q in pages() if q.stem == name]
    if len(hits) != 1:
        sys.exit(f"no single page called {name!r}")
    p = hits[0]
    d = reg[_page_type(p)]
    var, old = d["identity"], identity_of(p, reg)
    root = p.parent if _is_own(p, d, _type_dir(p, d["folder"])) else None
    below = [q for _, q in pages() if root and root in q.parents and q != p]
    moves, kept = [], []
    for q in [p] + below:
        qd = reg.get(_page_type(q))
        if not qd or "{%s}" % var not in qd["pattern"]:
            continue
        vals = {**variables(q, reg), var: value}
        if q != p and qd["identity"] != "none":
            vals[qd["identity"]] = identity_of(q, reg)
        new_name = _filename(_render(qd, vals))
        if new_name == q.stem:
            continue
        (kept if qd["ledger"] and q != p else moves).append((q, new_name))
    folder = (root, root.parent / _filename(value)) if root and old != value else None
    return moves, kept, folder

def rename(name, value, dry=False):
    moves, kept, folder = rename_plan(name, value)
    for q, n in moves:
        print(f"rename  {q.relative_to(VAULT)}  ->  {n}.md")
    if folder:
        print(f"folder  {folder[0].relative_to(VAULT)}/  ->  {folder[1].name}/")
    for q, n in kept:
        print(f"kept    {q.relative_to(VAULT)}  - a ledger entry keeps the name it was made with; "
              f"it would be {n}.md")
    if dry or not (moves or folder):
        return
    setting = _app()
    if setting is None:
        sys.exit("refused: renaming needs the running app, which rewrites every link to a renamed "
                 "page (obsidian.md). Open this vault in Obsidian, then run it again")
    if "true" not in setting:
        print("note: 'Automatically update internal links' is off, so Obsidian will ask before each rename",
              file=sys.stderr)
    for q, n in moves:
        r = subprocess.run(["obsidian", f"vault={VAULT.name}", "rename",
                            f"path={q.relative_to(VAULT).as_posix()}", f"name={n}"],
                           capture_output=True, text=True, timeout=60)
        if r.returncode != 0:
            sys.exit(f"stopped at {q.relative_to(VAULT)}: {r.stderr.strip() or r.stdout.strip()}")
    if folder:
        folder[0].rename(folder[1])    # filenames keep their links; only the folder's name changes
    tree()


# ---------------------------------------------------------------- cli
def _flag(args, name):
    return [args[i + 1] for i, a in enumerate(args) if a == name and i + 1 < len(args)]

if __name__ == "__main__":
    a = sys.argv[1:]
    if "--help" in a or "-h" in a:
        print(__doc__)              # never a command's side effects for a request for help
        sys.exit(0)
    cmd = a[0] if a else ""
    one = lambda name: (_flag(a, name) or [None])[0]
    plain = [x for i, x in enumerate(a[1:], 1)
             if not x.startswith("--") and not (i > 1 and a[i - 1] in
             ("--to", "--type", "--section", "--source", "--alias", "--set", "--owner", "--file"))]
    if cmd == "new" and plain:
        # A type one per owner has no name of its own: `new <type> --owner O`.
        print("created", new(plain[0], plain[1] if len(plain) > 1 else None, _flag(a, "--source"),
                             _flag(a, "--alias"), _flag(a, "--set"), one("--owner")).relative_to(VAULT))
    elif cmd == "graph":
        groups, search, where = graph("--print" not in a)
        for g in groups:
            print(f"  #{g['color']['rgb']:06x}  {g['query']}")
        print(f"  filter: {search}")
        print(f"{len(groups)} groups -> {where}")
    elif cmd == "open" and plain:
        print("opened", open_(plain[0], one("--type"), _flag(a, "--set"), one("--owner")).relative_to(VAULT))
    elif cmd == "prepare" and plain:
        print("prepared", prepare(plain[0], one("--type"), _flag(a, "--set"), one("--owner")).relative_to(VAULT))
    elif cmd == "fill" and len(plain) >= 2:
        f = one("--file")
        text = open(f, encoding="utf-8").read() if f else sys.stdin.read()
        print("filled", fill(plain[0], plain[1], text).relative_to(VAULT))
    elif cmd == "close":
        p = close(plain[0] if plain else None)
        print("closed", p.relative_to(VAULT) if p else "nothing - no open entry")
    elif cmd == "resume" and plain:
        print("resumed", resume(plain[0]).relative_to(VAULT))
    elif cmd == "current":
        reg = registry()
        for state, es in (("open", open_entries()), ("prepared", prepared_entries())):
            for t, p in es:
                o = owner_of(p, reg)
                print(f"{state:<9}{p.relative_to(VAULT)}" + (f"   ({o.stem}'s)" if o else ""))
        for t in needs_opening():
            print(f"needs    {t}: nothing open, so capture asks which occasion it is")
        if not ledgers():
            print("no ledger declared")
        elif not open_entries() and not needs_opening():
            print("no open entry")
    elif cmd == "log" and plain:
        print("logged to", log(" ".join(plain), one("--to"), "--local" in a, one("--section")).relative_to(VAULT))
    elif cmd == "tree":
        moved, linked = tree()
        for src, dst in moved:
            print(f"moved   {src.relative_to(VAULT)}  ->  {dst.relative_to(VAULT)}")
        if moved and subprocess.run(["sh", "-c", "ps -axco comm= | grep -qx Obsidian"]).returncode == 0:
            print("note: Obsidian is running - a moved page open in a tab with unsaved edits can be saved "
                  "back to its old place; reopen moved pages from the file explorer (obsidian.md)", file=sys.stderr)
        for p in linked:
            print(f"parent  {p.relative_to(VAULT)}")
        print(f"{len(moved)} moved, {len(linked)} parent link(s) written" if moved or linked
              else "every page is where its declaration puts it")
    elif cmd == "clues" and plain:
        clues(plain[0])
    elif cmd == "rename" and len(plain) >= 2:
        rename(plain[0], plain[1], "--dry-run" in a)
    else:
        print(__doc__)
        sys.exit(1)
